import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { format } from 'prettier';
import ts from 'typescript';

const root = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../..',
);
const check = process.argv.includes('--check');
const force = process.argv.includes('--force');
const marker =
  '// Generated by tools/application/generate-services.mjs. Do not edit by hand.';
const hashFile = path.join(root, 'tools/application/services.generated.json');
const hash = (value) => createHash('sha256').update(value).digest('hex');
const manualModels = new Set([
  'Note',
  'User',
  'UserSetting',
  'Family',
  'Child',
  'Pregnancy',
]);
const schema = await readFile(path.join(root, 'prisma/schema.prisma'), 'utf8');
const snake = (name) =>
  name.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();
const models = [...schema.matchAll(/^model\s+(\w+)\s*\{([\s\S]*?)^\}/gm)]
  .filter(([, name]) => !manualModels.has(name))
  .map(([, name, body]) => ({
    name,
    file: snake(name).replaceAll('_', '-'),
    token: snake(name).toUpperCase(),
    table: body.match(/@@map\("([^"]+)"\)/)?.[1] ?? name,
    schema: body.match(/@@schema\("([^"]+)"\)/)?.[1] ?? 'public',
  }));
if (models.length < 100)
  throw new Error('Complete family Prisma schema is required.');

let previousHashes = {};
try {
  previousHashes = JSON.parse(await readFile(hashFile, 'utf8')).files;
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
}
const files = new Map();
const summaries = [];
for (const model of models) {
  const { name, file, token } = model;
  const repositorySource = await readFile(
    path.join(
      root,
      `src/interfaces/repositories/${file}-repository.interface.ts`,
    ),
    'utf8',
  );
  const tree = ts.createSourceFile(
    `${file}.ts`,
    repositorySource,
    ts.ScriptTarget.Latest,
    true,
  );
  const contract = tree.statements.find(
    (node) =>
      ts.isInterfaceDeclaration(node) &&
      node.name.text === `I${name}Repository`,
  );
  if (!contract)
    throw new Error(`Missing typed repository contract for ${name}`);
  const methods = contract.members.map((method) => {
    if (
      !ts.isMethodSignature(method) ||
      !method.type ||
      !ts.isIdentifier(method.name)
    )
      throw new Error(`${name}: unsupported repository member`);
    const repositoryMethod = method.name.text;
    if (
      !['create', 'findByKey', 'list', 'update', 'softDelete'].includes(
        repositoryMethod,
      )
    )
      throw new Error(
        `${name}: review new repository method ${repositoryMethod}`,
      );
    const parameters = method.parameters.map((parameter) => {
      if (
        !ts.isIdentifier(parameter.name) ||
        !parameter.type ||
        parameter.questionToken ||
        parameter.dotDotDotToken
      )
        throw new Error(`${name}: unsupported repository parameter`);
      return { name: parameter.name.text, type: parameter.type.getText(tree) };
    });
    return {
      repositoryMethod,
      name: repositoryMethod === 'findByKey' ? 'getByKey' : repositoryMethod,
      parameters,
      returnType: ['findByKey', 'update'].includes(repositoryMethod)
        ? `Promise<${name}>`
        : repositoryMethod === 'softDelete'
          ? 'Promise<void>'
          : method.type.getText(tree),
    };
  });
  for (const required of ['create', 'findByKey', 'list'])
    if (!methods.some((method) => method.repositoryMethod === required))
      throw new Error(`${name}: missing repository method ${required}`);
  const updateInterface = tree.statements.find(
    (node) =>
      ts.isInterfaceDeclaration(node) &&
      node.name.text === `Update${name}Input`,
  );
  const updateFields =
    updateInterface?.members.map((member) => {
      if (!ts.isPropertySignature(member) || !ts.isIdentifier(member.name))
        throw new Error(`${name}: unsupported update input`);
      return member.name.text;
    }) ?? [];
  if (
    methods.some((method) => method.name === 'update') &&
    !updateFields.length
  )
    throw new Error(`${name}: update method has no mutable fields`);
  const inputTypes = [
    ...new Set(
      methods
        .flatMap((method) =>
          method.parameters.map((parameter) => parameter.type),
        )
        .filter((type) => type !== 'PaginationInput'),
    ),
  ];
  const parameterText = (method) =>
    method.parameters
      .map((parameter) => `${parameter.name}: ${parameter.type}`)
      .join(', ');
  const argumentText = (method) =>
    method.parameters.map((parameter) => parameter.name).join(', ');
  files.set(
    `src/interfaces/services/${file}-service.interface.ts`,
    `${marker}
import type { ${name} } from '../../models/${file}.model';
import type { Paginated, PaginationInput } from '../../common/pagination/pagination.types';
import type { ${inputTypes.join(', ')} } from '../repositories/${file}-repository.interface';
export const ${token}_SERVICE = Symbol('${token}_SERVICE');
/** Internal persistence-backed scaffolding. Callers must authorize scopes and orchestrate business workflows. No HTTP exposure is implied. */
export interface I${name}Service {
${methods.map((method) => `${method.name}(${parameterText(method)}): ${method.returnType};`).join('\n')}
}
`,
  );
  files.set(
    `src/services/${file}.service.ts`,
    `${marker}
import { Inject, Injectable } from '@nestjs/common';
import { NotFoundError } from '../common/errors/domain.error';
import { assertDatabasePagination${updateFields.length && methods.some((method) => method.name === 'update') ? ', assertDatabaseUpdate' : ''} } from '../common/database.validation';
import type { Paginated, PaginationInput } from '../common/pagination/pagination.types';
import type { ${name} } from '../models/${file}.model';
import { ${token}_REPOSITORY } from '../interfaces/repositories/${file}-repository.interface';
import type { I${name}Repository, ${inputTypes.join(', ')} } from '../interfaces/repositories/${file}-repository.interface';
import type { I${name}Service } from '../interfaces/services/${file}-service.interface';
/** Internal application boundary; authorization and multi-table workflows belong to dedicated callers. */
@Injectable()
export class ${name}Service implements I${name}Service {
constructor(@Inject(${token}_REPOSITORY) private readonly repository: I${name}Repository) {}
${methods
  .map((method) => {
    if (method.name === 'getByKey')
      return `async getByKey(${parameterText(method)}): ${method.returnType} {
const model = await this.repository.findByKey(${argumentText(method)});
if (!model) throw new NotFoundError('${name} was not found.');
return model;
}`;
    if (method.name === 'softDelete')
      return `async softDelete(${parameterText(method)}): ${method.returnType} {
if (!(await this.repository.softDelete(${argumentText(method)}))) throw new NotFoundError('${name} was not found.');
}`;
    if (method.name === 'update')
      return `async update(${parameterText(method)}): ${method.returnType} {
assertDatabaseUpdate(input, ${JSON.stringify(updateFields)});
const model = await this.repository.update(${argumentText(method)});
if (!model) throw new NotFoundError('${name} was not found.');
return model;
}`;
    return `${method.name}(${parameterText(method)}): ${method.returnType} {
${method.name === 'list' ? 'assertDatabasePagination(input);' : ''}
return this.repository.${method.repositoryMethod}(${argumentText(method)});
}`;
  })
  .join('\n')}
}
`,
  );
  summaries.push({
    model: name,
    schema: model.schema,
    table: model.table,
    methods: methods.map((method) => method.name),
    exposure: 'internal',
  });
}
files.set(
  'src/common/application/service.providers.ts',
  `${marker}
import type { Provider } from '@nestjs/common';
${models.map(({ name, file, token }) => `import { ${token}_SERVICE } from '../../interfaces/services/${file}-service.interface';\nimport { ${name}Service } from '../../services/${file}.service';`).join('\n')}
export const INTERNAL_SERVICE_PROVIDERS: Provider[] = [
${models.map(({ name, token }) => `{ provide:${token}_SERVICE, useClass:${name}Service },`).join('\n')}
];
`,
);
files.set(
  'src/common/application/service.manifest.ts',
  `${marker}
export const INTERNAL_SERVICE_TABLES = ${JSON.stringify(summaries, null, 2)} as const;
`,
);
const rendered = await Promise.all(
  [...files].map(async ([name, content]) => [
    name,
    await format(content, {
      parser: 'typescript',
      singleQuote: true,
      trailingComma: 'all',
    }),
  ]),
);
const targets = await Promise.all(
  rendered.map(async ([name, content]) => {
    let existing;
    try {
      existing = await readFile(path.join(root, name), 'utf8');
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
    return { name, content, existing };
  }),
);
// Validate every destination before writing any source.
for (const { name, existing } of targets) {
  if (existing !== undefined && !existing.startsWith(marker))
    throw new Error(`Refusing to overwrite hand-written ${name}`);
  if (
    existing !== undefined &&
    previousHashes[name] !== undefined &&
    hash(existing) !== previousHashes[name] &&
    (!force || check)
  )
    throw new Error(
      `Generated file was customized: ${name}. Preserve your changes before using --force.`,
    );
}
const changed = targets.filter(
  ({ content, existing }) => content !== existing,
).length;
if (check && changed) {
  process.stderr.write(
    `${changed} service files differ; regenerate before committing.\n`,
  );
  process.exitCode = 1;
} else if (check)
  process.stdout.write(
    `Verified ${models.length} internal services/interfaces (${files.size} files).\n`,
  );
else {
  for (const { name, content, existing } of targets)
    if (content !== existing) {
      await mkdir(path.dirname(path.join(root, name)), { recursive: true });
      await writeFile(path.join(root, name), content);
    }
  await writeFile(
    hashFile,
    JSON.stringify(
      {
        version: 1,
        files: Object.fromEntries(
          rendered.map(([name, content]) => [name, hash(content)]),
        ),
      },
      null,
      2,
    ) + '\n',
  );
  process.stdout.write(
    `Generated ${models.length} internal services/interfaces (${files.size} files).\n`,
  );
}
